import { Controller, Get } from '@nestjs/common';
import { HealthCheckService, HealthCheck, TypeOrmHealthIndicator } from '@nestjs/terminus';
import { RedisHealthIndicator } from './redis-health.indicator';

@Controller('health')
export class HealthController {
  constructor(
    private readonly health: HealthCheckService,
    private readonly db: TypeOrmHealthIndicator,
    private readonly redis: RedisHealthIndicator,
  ) {}

  // Wired to the Deployment's livenessProbe: failure ⇒ kubelet KILLS and restarts the pod.
  @Get('live')
  @HealthCheck()
  checkLiveness() {
    return this.health.check([
      // Legitimate: a wedged/corrupted in-process DB connection pool IS fixable by a restart.
      () => this.db.pingCheck('database'),
      // BUG: Redis is a shared downstream, not something a restart of THIS pod can repair.
      // Putting it in the liveness set means one Redis outage fails EVERY replica's
      // liveness check at once, and the resulting restart never revives Redis, so the
      // new pod fails liveness again the moment it comes up — an amplifying restart loop.
      () => this.redis.pingCheck('redis'),
    ]);
  }

  // Wired to the Deployment's readinessProbe: failure ⇒ pod pulled from Service endpoints, NO restart.
  @Get('ready')
  @HealthCheck()
  checkReadiness() {
    return this.health.check([
      () => this.db.pingCheck('database'),
      // Correct here: readiness failure just stops routing traffic to this pod
      // and self-heals the moment Redis comes back — no restart involved.
      () => this.redis.pingCheck('redis'),
    ]);
  }
}

